    const elements = Array.from(document.querySelectorAll('*'));
    const battingElements = elements.filter(el => el.innerText && el.innerText.includes('Batting') && el.tagName.match(/H[1-6]/));
    let results = [];
    battingElements.forEach(el => {
        let next = el.nextElementSibling;
        while (next && next.tagName !== 'TABLE') {
            next = next.nextElementSibling;
